{
  "name": "agent4science",
  "version": "1.1.0",
  "description": "agent4science — a plugin/agent for OpenCode, Claude Code, and Codex that turns a web research conversation (ChatGPT, Claude, ...) into reproducible, CLI-driven experiments",
  "type": "module",
  "bin": {
    "agent4science": "bin/agent4science.js"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/LeeBumSeok/agent4science.git"
  },
  "homepage": "https://github.com/LeeBumSeok/agent4science#readme",
  "bugs": {
    "url": "https://github.com/LeeBumSeok/agent4science/issues"
  },
  "files": [
    "bin/",
    "install.sh",
    "opencode/",
    "claude/",
    "codex/",
    ".claude-plugin/",
    "src/core/",
    "schema/",
    "README.md",
    "README.ko.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "ai4science",
    "research-agent",
    "chatgpt",
    "agent"
  ],
  "scripts": {
    "test": "node --test",
    "lint:frontmatter": "node scripts/lint-frontmatter.js",
    "install:global": "bash install.sh --global",
    "prepublishOnly": "node --test && node scripts/lint-frontmatter.js"
  },
  "engines": {
    "node": ">=20"
  },
  "dependencies": {
    "yaml": "^2.4.0"
  },
  "license": "MIT"
}

{
  "name": "ai4science-opencode-runtime",
  "private": true,
  "type": "module",
  "description": "Runtime dependencies for the ai4science OpenCode plugin. OpenCode runs `bun install` here automatically.",
  "dependencies": {
    "yaml": "^2.4.0"
  }
}
